function Get-WinUtilAppIcon {
    <#
    .SYNOPSIS
        Returns the application icon BitmapImage for Windows-Tweaks-Hub (Ri.ico).
    #>
    [CmdletBinding()]
    param()

    # Try local file first
    $localPaths = @(
        ".\assets\Ri.ico"
    )
    if (-not [string]::IsNullOrWhiteSpace($PSScriptRoot)) {
        $localPaths = @((Join-Path $PSScriptRoot "..\..\assets\Ri.ico")) + $localPaths
    }

    foreach ($p in $localPaths) {
        if (-not [string]::IsNullOrWhiteSpace($p) -and (Test-Path -LiteralPath $p -ErrorAction SilentlyContinue)) {
            try {
                $bytes = [System.IO.File]::ReadAllBytes((Resolve-Path -LiteralPath $p).Path)
                $ms = New-Object System.IO.MemoryStream(,$bytes)
                $img = New-Object System.Windows.Media.Imaging.BitmapImage
                $img.BeginInit()
                $img.StreamSource = $ms
                $img.CacheOption = [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
                $img.EndInit()
                if ($img.CanFreeze) {
                    $img.Freeze()
                }
                return $img
            } catch {}
        }
    }

    # Fallback to embedded base64 icon
    $base64 = ""
    try {
        $bytes = [Convert]::FromBase64String($base64)
        $ms = New-Object System.IO.MemoryStream(,$bytes)
        $img = New-Object System.Windows.Media.Imaging.BitmapImage
        $img.BeginInit()
        $img.StreamSource = $ms
        $img.CacheOption = [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
        $img.EndInit()
        if ($img.CanFreeze) {
            $img.Freeze()
        }
        return $img
    } catch {
        return $null
    }
}
